const tabsOf=c=>c.tabs.filter(t=>t.tabId!==87&&!t.isEmpty).sort((a,b)=>a.sortOrder-b.sortOrder||a.tabName.localeCompare(b.tabName));
const labelTab=(c,t)=>({'Primalist:Life':'Grovekeeper','Primalist:Primal':'Wildwalker','Runemaster:Runic':'Engravement','Runemaster:Arcane':'Glyphic','Venomancer:Venom':'Rotweaver'}[c.name+':'+t.tabName]||t.tabName);
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4500);}
async function json(file){if(!cache.has(file))cache.set(file,fetch('./data/'+file).then(r=>{if(!r.ok)throw Error('Could not load '+file+' ('+r.status+')');return r.json();}).catch(e=>{cache.delete(file);throw e;}));return cache.get(file);}
function classFrom(key){return classes.find(c=>c.key===key||slug(c.name)===key||String(c.id)===String(key))||classes[0];}
function byClass(name){return classes.find(c=>c.name===name);}
function nodeDescription(n,rank=1){return n.rankDescriptions.find(r=>r.rank===rank)?.description||n.description||'No description was preserved for this talent.';}
function humanRole(role){return ({melee:'Melee damage',ranged:'Ranged damage',caster:'Spell damage',tank:'Tank',healer:'Healer',support:'Support',hybrid:'Hybrid', 'hybrid-healer':'Hybrid healer'})[role]||'Role under research';}
function roleSummary(role){return ({melee:'A close-range damage path; its weapon choices and attack flow are specific to this CoA tree.',ranged:'A ranged damage path; this tree defines its weapon style and combat rhythm.',caster:'A spell-damage path; the CoA tree defines its spell theme and casting flow.',tank:'A frontline path built around surviving pressure and protecting the group.',healer:'A healing path built around keeping allies alive with this tree’s own tools.',support:'A group-support path; its utility and secondary effects are specific to this tree.','hybrid-healer':'A hybrid path that combines healing with this tree’s own damage and utility tools.'})[role]||'This specialization has a CoA-specific role and toolkit.';}
function specMeta(c,t){const name=labelTab(c,t);return (window.BONE_SPECS||[]).find(s=>s.name===c.name+' — '+name)|| (window.BONE_SPECS||[]).find(s=>s.name===c.name+' — '+t.tabName);}
function sourceBar(){return '<div class="sourcebar ba-credit"><strong>BoneArchive Research</strong> · Curated & maintained by Uncle Bone · Sources and provenance are collected in the Sources section.</div>';}
function renderSidebar(selected){$('#class-list').innerHTML=classes.map((c,i)=>'<a class="classlink '+(selected===c.key?'current':'')+'" style="--classcolor:'+COLORS[i%COLORS.length]+'" href="'+url('class',{class:c.key})+'">'+classIcon(c,'classnav-mark')+'<span>'+esc(c.name)+'</span><span class="arrow">›</span></a>'+(selected===c.key?'<div class="subspecs">'+tabsOf(c).map(t=>'<a href="'+url('class',{class:c.key,spec:t.tabId})+'">'+esc(labelTab(c,t))+'</a>').join('')+'</div>':'')).join('');}
function hero(eyebrow,title,copy,actions=''){return '<section class="hero"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="./">Archive home</a><span aria-hidden="true">›</span><span>'+esc(eyebrow)+'</span></nav><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+copy+'</p>'+actions+'</section>';}
function tile(c,i){return '<a class="class-tile" style="--classcolor:'+COLORS[i%COLORS.length]+'" href="'+url('class',{class:c.key})+'">'+classIcon(c,'class-tile-mark')+'<strong>'+esc(c.name)+'</strong><small>'+tabsOf(c).map(t=>esc(labelTab(c,t))).join(' · ')+'</small></a>';}
