async function rankingsPage(params,token){const data=await json('sidekick-specs.json');if(token!==routeToken)return;const query=params.get('q')||'',entries=data.entries||[];app.innerHTML=hero('Community comparison','Specialization index<br><em>21 classes · 70 specs</em>','Compare Ascension Sidekick’s community estimates by dungeon, raid, arena, and battleground. Open any BoneArchive guide for its preserved class data, talent tree, and research context.','<nav class="links"><a href="'+url('picker')+'">Find a specialization →</a><a href="'+url('library')+'">Review sources & evidence</a></nav>')+'<section class="sidekick-index"><div class="sidekick-index-head"><div><span class="eyebrow">ASCENSION SIDEKICK · COMMUNITY REFERENCE</span><h2>Every specialization</h2><p>Captured '+esc(data.captured)+' · Popularity is community interest, not in-game pick rate.</p></div><label>Filter classes or specs<input id="sidekick-filter" type="search" placeholder="Search 21 classes and 70 specs" value="'+esc(query)+'"></label></div><div class="sidekick-index-groups">'+[...new Set(entries.map(x=>x.class))].sort().map(cls=>'<section class="sidekick-class-group" data-class="'+esc(cls.toLowerCase())+'"><h3>'+esc(cls)+' <small>'+entries.filter(x=>x.class===cls).length+' specs</small></h3><div class="sidekick-spec-grid">'+entries.filter(x=>x.class===cls).map(x=>{const own=byClass(x.class),tab=own&&tabsOf(own).find(t=>slug(labelTab(own,t))===slug(x.spec)||slug(t.tabName)===slug(x.spec)||((x.spec==='Rot'||x.spec==='Rotweaver')&&/Rot/i.test(labelTab(own,t))));const ownUrl=own?url('class',{class:own.key,spec:tab?.tabId}):'#';return '<article class="sidekick-spec-row" data-search="'+esc((x.class+' '+x.spec+' '+x.archiveRole+' '+x.difficulty.floor+' '+x.difficulty.ceiling).toLowerCase())+'"><div><a class="sidekick-spec-name" href="'+ownUrl+'">'+esc(x.spec)+'</a><span class="sidekick-role">'+esc(humanRole(x.archiveRole))+'</span><a class="sidekick-source-link" href="'+esc(x.sourceUrl)+'" target="_blank" rel="noopener">Sidekick ↗</a></div><div class="sidekick-spec-ratings">'+Object.entries({dungeon:'Dun',raid:'Raid',arena:'Arena',battlegrounds:'BG'}).map(([k,l])=>'<span title="'+l+'"><small>'+l+'</small><b class="tier-'+esc(x.ratings[k].toLowerCase())+'">'+esc(x.ratings[k])+'</b></span>').join('')+'</div><span class="sidekick-difficulty-mini">'+esc(({low:'Beginner',medium:'Moderate',high:'Advanced','very-high':'Expert'})[x.difficulty.floor])+'<small>Floor · '+esc(x.difficulty.ceiling)+' ceiling</small></span><span class="sidekick-popularity" title="Sidekick community interest index">'+x.popularity+'%<small>interest</small></span></article>';}).join('')+'</div></section>').join('')+'</div><p class="weight-caveat">'+esc(data.method)+' <a href="'+esc(data.source)+'" target="_blank" rel="noopener">Open the full Sidekick tier list ↗</a></p></section><section class="sidekick-reference-note"><h2>How to use this index</h2><p>Start with the class and specialization record for CoA abilities, resources, gear rules, and talents. Treat Sidekick ratings as a second opinion to investigate; use our combat-log and research sections for evidence tied to captured data.</p><a href="'+url('library')+'">Open research sources →</a></section>';const input=$('#sidekick-filter');input.oninput=()=>{const q=input.value.trim().toLowerCase();let visible=0;for(const group of $$('.sidekick-class-group')){let n=0;for(const row of $$('.sidekick-spec-row',group)){const show=row.dataset.search.includes(q);row.hidden=!show;if(show)n++;}group.hidden=n===0;if(n)visible+=n;}let emptyNode=$('#sidekick-filter-empty');if(!emptyNode){emptyNode=document.createElement('p');emptyNode.id='sidekick-filter-empty';emptyNode.className='empty';input.closest('.sidekick-index-head').after(emptyNode);}emptyNode.hidden=visible>0;emptyNode.textContent=visible?'': 'No class or specialization matches that search.';};}
