function talentEffectsHtml(classNodes,specNodes){const stat=/\b(?:strength|agility|stamina|intellect|spirit|armor|defen[cs]e|dodge|parry|hit(?: rating| chance)?|expertise|critical strike(?: rating| chance)?|haste(?: rating)?|attack power|ranged attack power|spell power|healing power|block(?: chance| rating| value)?|armor penetration|spell penetration|resilience|health|mana|energy|rage|focus|insanity|runic power)\b/i,change=/\b(?:increase|increases|increased|decrease|decreases|reduced|reduces|gain|gains|grant|grants|convert|converts|scale|scales|equal to|based on|in addition|while|when you|every|each stack|per point|chance to hit|chance to dodge|chance to parry)\b/i;const select=nodes=>nodes.filter(n=>{const text=(n.description||'')+' '+(n.rankDescriptions||[]).map(x=>x.description||'').join(' ');return stat.test(text)&&change.test(text)&&/\b(?:you|your|while|when|enter|exit|each|every|per|active|equipped|form)\b/i.test(text);}).filter((n,i,a)=>a.findIndex(x=>x.id===n.id)===i);const groups=[['Shared class tree',select(classNodes)],['Specialization tree',select(specNodes)]],count=groups.reduce((n,x)=>n+x[1].length,0),renderGroup=([title,nodes])=>nodes.length?'<details class="effect-group" open><summary>'+esc(title)+' · '+nodes.length+' talents</summary><div class="effect-list">'+nodes.map(n=>'<details class="effect-row"><summary><span>'+esc(n.name)+'</span><small>'+(n.isPassive||/passive/i.test(n.description||'')?'Passive':'Talent')+'</small></summary><p>'+esc((n.rankDescriptions||[]).find(x=>x.rank===1)?.description||n.description||'No description was preserved.')+'</p></details>').join('')+'</div></details>':'';return {count,html:groups.map(renderGroup).join('')||'<div class="card">No stat-changing talent text was matched in the saved tree.</div>'};}
