function topBuildsSection(data,community,cls,tab){const specs=(window.BONE_SPECS||[]);const specName=cls&&tab?labelTab(cls,tab):'';const specKey=cls&&tab?cls.name+' — '+specName:'';const verified=(data.entries||[]).filter(x=>!cls||x.classKey===cls.key).filter(x=>!tab||Number(x.specId)===Number(tab.tabId));const entries=(community.entries||[]).filter(x=>!cls||x.classKey===cls.key).filter(x=>!tab||Number(x.specId)===Number(tab.tabId)).sort((a,b)=>b.netScore-a.netScore||b.upvotes-a.upvotes||b.views-a.views||a.title.localeCompare(b.title));const top=entries.slice(0,3);const card=x=>'<article class="card"><span class="tag">Community votes · '+esc(x.contentType||'archived')+'</span><h3>'+esc(x.title)+'</h3>'+(x.description?'<p>'+esc(x.description.slice(0,520))+(x.description.length>520?'…':'')+'</p>':'')+'<p class="muted">'+esc(x.className)+' · '+esc(x.specName)+' · '+esc(x.patchVersion||'version not recorded')+' · '+esc((x.tags||[]).join(' · '))+'</p><p class="muted">▲ '+esc(x.upvotes)+' · ▼ '+esc(x.downvotes)+' · '+esc(x.views)+' archived views</p><a class="button" href="'+url('builder',{class:x.classKey,spec:x.specId,level:60,p:x.allocations.map(a=>a.id+'.'+a.points).join(',')})+'">Load exact talent build</a></article>';const label=tab?esc(specName):cls?esc(cls.name):'all archived specializations';return '<section class="top-builds-section"><div class="sectionline"><div><span class="eyebrow">COMMUNITY BUILD ARCHIVE</span><h2>Top builds · '+label+'</h2></div><span class="archive-wordmark">Ranked by archived votes</span></div><p class="notice">These are identity-stripped community builds, ordered by archived votes, then views. Votes and views measure community activity, not combat performance. Only allocations fully matched to current talents are loadable.</p>'+(top.length?'<div class="cards">'+top.map(card).join('')+'</div>':'<article class="card top-builds-empty"><span class="tag">No matched archive build</span><h3>No loadable community build found'+(specKey?' for this specialization':' in this archive view')+'</h3><p>The preserved source records contain builds for 64 of 70 specializations. Builds appear here only when every talent can be matched to the current tree.</p></article>')+(entries.length>3?'<details class="community-build-more"><summary>Show all '+entries.length+' matched builds</summary><div class="cards">'+entries.slice(3).map(card).join('')+'</div></details>':'')+'<p class="muted">Imported '+entries.length+' of 128 source records after current talent matching. Identities and comments are omitted. <a href="'+esc(community.sourceUrl)+'" target="_blank" rel="noopener">Open preserved CoA Build Hub source ↗</a> · <a href="'+esc(community.sourceReadme)+'" target="_blank" rel="noopener">About the archive ↗</a></p></section>'+(verified.length?'<section class="top-builds-section"><h2>Research-backed builds</h2><div class="cards">'+verified.map(x=>'<article class="card"><span class="tag">'+esc(x.evidence||'Research record')+'</span><h3>'+esc(x.name)+'</h3><p>'+esc(x.summary)+'</p><a class="button" href="'+url('builder',{class:x.classKey,spec:x.specId,level:x.level||60,p:x.points})+'">Open this build</a></article>').join('')+'</div></section>':'');}
function treeHtml(tab,data,model){const nodes=model.nodes.filter(n=>n.tabId===tab.tabId),ids=new Set(nodes.map(n=>n.id)),groups=new Map();for(const n of nodes){const key=n.x+':'+n.y;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(n);}const pos=n=>({x:n.x+1,y:n.y+1});let edges='';for(const n of nodes)for(const id of n.connectedNodeIds||[]){if(!ids.has(id))continue;const p=pos(model.byId.get(id)),q=pos(n);edges+='<path class="tree-edge" data-from="'+id+'" data-to="'+n.id+'" d="M '+p.x+' '+p.y+' L '+q.x+' '+q.y+'"/>';}
const gates=[...new Set(nodes.map(n=>tab.tabId===87?n.reqTabAE:n.reqTabTE).filter(Boolean))].sort((a,b)=>a-b).map(g=>{const y=Math.min(...nodes.filter(n=>(tab.tabId===87?n.reqTabAE:n.reqTabTE)===g).map(n=>n.y));return '<span class="gate-label" style="top:'+((y+.4)/12*100)+'%">'+g+' '+(tab.tabId===87?'Ability':'Talent')+' Essence invested</span>';}).join('');
return '<section class="tree-panel"><h2>'+esc(tab.tabId===87?data.builderClassName+' · Class tree':tab.tabName)+'</h2><div class="tree-scroll"><div class="tree-canvas"><svg viewBox="0 0 12 12" aria-hidden="true">'+edges+'</svg>'+gates+nodes.map(n=>{const pair=groups.get(n.x+':'+n.y),choice=pair.length>1,offset=choice?(pair.indexOf(n)===0?-.24:.24):0;return '<button type="button" class="talent-node '+(n.nodeType==='SpendCircle'?'circle ':'')+(choice?'choice-node ':'')+'" data-id="'+n.id+'" aria-describedby="tooltip" style="left:'+((n.x+1+offset)/12*100)+'%;top:'+((n.y+1)/12*100)+'%"><span class="fallback">'+esc(n.name.split(' ').map(x=>x[0]).join('').slice(0,2))+'</span>'+image(n)+'<span class="rank"></span></button>';}).join('')+'</div></div><div class="tree-legend">'+(tab.tabId===87?'Ability Essence · ':'Talent Essence · ')+nodes.length+' nodes · Gold: selected · Blue: granted · Gray: locked</div></section>';}
function updateBuild(replace=true){const {model,c,tab}=builder,sum=model.totals();$('#ae-count').textContent=sum.ae+' / '+model.budget.ae;$('#te-count').textContent=sum.te+' / '+model.budget.te;for(const b of $$('.talent-node',app)){const n=model.byId.get(+b.dataset.id),r=model.rank(n),free=model.free(n),why=model.reason(n);b.classList.toggle('selected',!free&&r>0);b.classList.toggle('granted',free&&r>0);b.classList.toggle('locked',!r&&!!why);b.classList.toggle('available',!why);b.setAttribute('aria-label',n.name+', '+(free?'granted at level '+Math.max(10,TalentModel.levelRequired(n)):'rank '+r+' of '+n.maxPoints)+(n.group?', choice talent':''));b.setAttribute('aria-pressed',String(r>0));$('.rank',b).textContent=free?'◆':r+'/'+n.maxPoints;}
for(const p of $$('.tree-edge',app)){const a=model.byId.get(+p.dataset.from),b=model.byId.get(+p.dataset.to);p.classList.toggle('active',model.rank(a)>0&&model.rank(b)>0);}
const u=new URL(location.href);u.search='';u.searchParams.set('view','builder');u.searchParams.set('class',c.key);u.searchParams.set('spec',tab.tabId);u.searchParams.set('level',model.level);const points=Object.entries(model.ranks).filter(([,v])=>v>0).sort((a,b)=>+a[0]-+b[0]).map(([id,r])=>id+'.'+r).join(',');if(points)u.searchParams.set('p',points);$('#share-link').value=u.href;if(replace)history.replaceState({},'',u);
const selected=model.nodes.filter(n=>!model.free(n)&&model.rank(n)>0);$('#selected-talents').innerHTML=selected.length?selected.map(n=>'<article class="summary-talent">'+image(n)+'<div><h3>'+esc(n.name)+' <span class="tag">'+model.rank(n)+'/'+n.maxPoints+'</span></h3><p>'+esc(nodeDescription(n,model.rank(n)))+'</p></div></article>').join(''):empty('No points spent yet. Pick talents in either tree to start your build.');wireImages();}
function tipHtml(n){const m=builder.model,r=m.rank(n),why=m.reason(n),next=Math.min(n.maxPoints,Math.max(1,r+1));return '<h3>'+esc(n.name)+'</h3><div class="rank-label">'+(m.free(n)?'Granted · Level '+Math.max(10,TalentModel.levelRequired(n)):'Rank '+r+' / '+n.maxPoints)+' · Spell '+(n.spellIds[Math.max(0,r-1)]||n.spellId)+'</div><div class="muted">'+n.aeCost+' Ability Essence · '+n.teCost+' Talent Essence per rank'+(n.group?' · Choose one of two':'')+'</div><p>'+esc(nodeDescription(n,Math.max(1,r)))+'</p>'+(r>0&&r<n.maxPoints?'<div class="rank-label">Next rank</div><p>'+esc(nodeDescription(n,next))+'</p>':'')+(why&&!m.free(n)&&r<n.maxPoints?'<div class="restriction">'+esc(why)+'</div>':'')+'<div class="muted">Click: add · Shift/right-click: remove</div>';}
function showTip(n,anchor){if(!builder)return;tooltipNode=n;const tip=$('#tooltip');tip.innerHTML=tipHtml(n);tip.hidden=false;const r=anchor.getBoundingClientRect(),w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(12,Math.min(innerWidth-w-12,r.right+12))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-h-12,r.top-12))+'px';}
