function showDetail(n){const m=builder.model;$('#talent-detail').innerHTML='<div class="sectionline" style="margin:0">'+image(n)+'<h3 style="margin-right:auto">'+esc(n.name)+'</h3><span class="tag">'+m.rank(n)+' / '+n.maxPoints+'</span></div><p class="detail-copy">'+esc(nodeDescription(n,Math.max(1,m.rank(n))))+'</p><div class="muted">Spell '+n.spellId+' · '+esc(n.entryType)+(n.group?' · Exclusive choice':'')+'</div>'+(m.reason(n)?'<p class="muted">'+esc(m.reason(n))+'</p>':'')+'<div class="rank-actions"><button class="button secondary" id="detail-remove" aria-label="Remove rank from '+esc(n.name)+'">− Remove rank</button><button class="button" id="detail-add" aria-label="Add rank to '+esc(n.name)+'">+ Add rank</button></div><details><summary>View all preserved ranks</summary>'+n.rankDescriptions.map(r=>'<p><strong>Rank '+r.rank+' · Spell '+r.spellId+'</strong><br>'+esc(r.description)+'</p>').join('')+'</details>';$('#detail-remove').onclick=()=>{m.remove(n.id);updateBuild();showDetail(n);};$('#detail-add').onclick=()=>{const why=m.add(n.id);if(why)toast(why);updateBuild();showDetail(n);};wireImages();}
function exportBuild(){return {format:'bonearchive-build',version:1,name:builder.c.name+' · '+labelTab(builder.c,builder.tab),class:builder.c.key,spec:builder.tab.tabId,level:builder.model.level,points:builder.model.ranks,treeSnapshot:'2026-08-12'};}
function readSaved(){try{return JSON.parse(localStorage.getItem('bonearchive.builds.v1')||'[]');}catch{return [];}}
function saveBuild(){const value=exportBuild(),saved=readSaved(),key=JSON.stringify([value.class,value.spec,value.level,value.points]);if(saved.some(s=>s.key===key)){toast('This build is already saved on this device.');return;}const id=Date.now().toString(36);saved.unshift({...value,key,id,url:$('#share-link').value,savedAt:new Date().toISOString()});try{localStorage.setItem('bonearchive.builds.v1',JSON.stringify(saved.slice(0,100)));toast('Build saved on this device. Open My saved builds to return to it.');}catch{toast('Device storage is unavailable. Copy the build link instead.');}}
function importBuild(){try{const text=$('#import-text').value.trim();if(!text)throw Error('Paste a build URL or JSON first.');let value;if(text.startsWith('{')){value=JSON.parse(text);if(value.format!=='bonearchive-build'||value.version!==1)throw Error('Unsupported build format.');}else{const u=new URL(text,location.href);if(u.searchParams.get('view')!=='builder')throw Error('This is not a BoneArchive build link.');if(!classes.some(c=>c.key===u.searchParams.get('class')))throw Error('Unknown class.');const target=new URL(location.href);target.search=u.search;navigate(target);return;}const c=classes.find(c=>c.key===value.class);if(!c||!tabsOf(c).some(t=>t.tabId===+value.spec))throw Error('Unknown class or specialization.');const entries=Object.entries(value.points||{});if(entries.length>500)throw Error('Too many talent entries.');const p=entries.filter(([id,r])=>/^\d+$/.test(id)&&Number.isInteger(r)&&r>0&&r<=10).map(([id,r])=>id+'.'+r).join(',');navigate(new URL(url('builder',{class:c.key,spec:value.spec,level:value.level,p}),location.href));}catch(e){toast(e.message);}}
async function savedPage(){const list=readSaved();app.innerHTML=hero('My builds · Saved on this device','Your next adventure,<br><em>ready when you are.</em>','Saved builds stay in this browser. Use a share link or JSON export to move a build to another device.')+(list.length?'<div class="cards">'+list.map(s=>'<article class="card"><h3>'+esc(s.name)+'</h3><p>Level '+esc(s.level)+' · '+Object.values(s.points).reduce((a,b)=>a+b,0)+' ranks selected</p><p class="muted">Saved '+new Date(s.savedAt).toLocaleDateString()+'</p><a class="button" href="'+esc(new URL(s.url,location.href).pathname+new URL(s.url,location.href).search)+'">Open build</a><button class="button secondary small" data-remove-saved="'+esc(s.id)+'">Remove</button></article>').join('')+'</div>':empty('No saved builds yet. Open a talent tree and choose Save build.'));for(const b of $$('[data-remove-saved]'))b.onclick=()=>{try{localStorage.setItem('bonearchive.builds.v1',JSON.stringify(readSaved().filter(s=>s.id!==b.dataset.removeSaved)));savedPage();}catch{toast('Could not update device storage.');}};}
async function searchPage(params,token){const term=(params.get('q')||'').trim();app.innerHTML=hero('Archive search','Find your<br><em>next idea.</em>','Search classes, specializations, talent names, descriptions, and spell IDs.','<form id="page-search" class="sharebox"><input id="search-query" aria-label="Search archive" value="'+esc(term)+'" placeholder="Try Shadow Brand, healing, or a spell ID"><button class="button">Search</button></form>')+'<div id="search-content" role="status">'+(term?'Searching preserved trees…':'Enter a search to explore the archive.')+'</div>';$('#page-search').onsubmit=e=>{e.preventDefault();go('search',{q:$('#search-query').value});};if(!term)return;const all=await Promise.all(classes.map(c=>json(c.key+'.json').then(d=>({c,d}))));if(token!==routeToken)return;const q=term.toLowerCase(),hits=[];for(const {c,d} of all)for(const n of d.nodes)if([c.name,n.name,n.description,n.spellId,d.tabs.find(t=>t.tabId===n.tabId)?.tabName].join(' ').toLowerCase().includes(q))hits.push({c,n});let shown=40;function paint(){$('#search-content').innerHTML='<div class="scope-count">'+hits.length+' matching talent nodes · showing '+Math.min(shown,hits.length)+'</div><div class="spell-grid">'+hits.slice(0,shown).map(x=>spellCard(x.c,x.n)).join('')+'</div>'+(shown<hits.length?'<button id="more-search" class="button secondary">Show 40 more</button>':'')+(!hits.length?empty('No matching talents were found. Try a different spell, class, or keyword.'):'');const b=$('#more-search');if(b)b.onclick=()=>{shown+=40;paint();};wireImages();}paint();}
async function spellsPage(params,token){const c=params.get('class')?classFrom(params.get('class')):null;if(!c){app.innerHTML=hero('Talent & ability index','The details behind<br><em>every build.</em>','Browse the preserved talent and ability entries for all 21 classes, including every available rank and spell ID.')+'<div class="class-grid">'+classes.map((c,i)=>tile(c,i).replace(url('class',{class:c.key}),url('spells',{class:c.key}))).join('')+'</div>';return;}const data=await json(c.key+'.json');if(token!==routeToken)return;renderSidebar(c.key);app.innerHTML=hero('Ability index · '+esc(c.name),esc(c.name)+'<br><em>Inside the spellbook.</em>','Search talent effects and inspect every preserved rank. This is the talent-node ability index; trainer-only and hidden triggered spells are not included.')+'<div class="toolbar"><input id="spell-filter" type="search" aria-label="Filter abilities" placeholder="Search names, effects, spell IDs…"><select id="spell-tab" aria-label="Filter ability tree"><option value="">All trees</option>'+c.tabs.map(t=>'<option value="'+t.tabId+'" '+(String(t.tabId)===params.get('spec')?'selected':'')+'>'+esc(t.tabName)+'</option>').join('')+'</select></div><div id="spell-count" class="scope-count"></div><div id="spell-results" class="spell-grid"></div>'+sourceBar(c);const paint=()=>{const q=$('#spell-filter').value.toLowerCase(),tab=$('#spell-tab').value;const matches=data.nodes.filter(n=>(!tab||String(n.tabId)===tab)&&[n.name,n.description,n.spellId].join(' ').toLowerCase().includes(q));$('#spell-count').textContent=matches.length+' matching talent and ability entries';$('#spell-results').innerHTML=matches.map(n=>spellCard(c,n)).join('');wireImages();};$('#spell-filter').oninput=paint;$('#spell-tab').onchange=paint;paint();}
async function pickerPage(){app.innerHTML=hero('Find my spec','A character that<br><em>plays your way.</em>','Choose the kind of role and combat style you enjoy. These matches use preserved role metadata—not invented performance scores.')+'<form class="picker-form" id="picker"><fieldset><legend>What do you want to do?</legend>'+[['damage','Deal damage'],['tank','Protect the group'],['healer','Keep allies alive'],['support','Support and hybrid play']].map(([v,l],i)=>'<label><input type="radio" name="role" value="'+v+'" '+(!i?'checked':'')+'>'+l+'</label>').join('')+'</fieldset><fieldset><legend>Where do you like to fight?</legend>'+[['any','Either works'],['melee','In melee range'],['ranged','From a distance']].map(([v,l],i)=>'<label><input type="radio" name="range" value="'+v+'" '+(!i?'checked':'')+'>'+l+'</label>').join('')+'</fieldset><button class="button">Find matching specializations</button></form><div id="picker-results"></div>';$('#picker').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),role=f.get('role'),range=f.get('range');const matches=(window.BONE_SPECS||[]).filter(s=>{const roleMatch=role==='damage'?['melee','ranged','caster'].includes(s.role):role==='healer'?['healer','hybrid-healer'].includes(s.role):role==='support'?['support','hybrid','hybrid-healer'].includes(s.role):s.role==='tank';return roleMatch&&(range==='any'||range==='melee'?range==='any'||['melee','tank','hybrid'].includes(s.role):['ranged','caster','healer','support','hybrid-healer'].includes(s.role));});$('#picker-results').innerHTML='<h2>'+matches.length+' specializations to explore</h2><div class="cards">'+matches.map(s=>{const [cl,sp]=s.name.split(' — '),c=byClass(cl),t=c&&tabsOf(c).find(t=>labelTab(c,t)===sp);return c&&t?'<article class="card"><h3>'+esc(sp)+'</h3><span class="tag">'+esc(humanRole(s.role))+'</span><p>'+esc(cl)+'</p><a href="'+url('class',{class:c.key,spec:t.tabId})+'">Explore this specialization →</a></article>':'';}).join('')+'</div>'+(matches.length?'':empty('No exact matches. Try either range to see more options.'));};}
async function macrosPage(params,token){const c=classFrom(params.get('class')),data=await json(c.key+'.json');if(token!==routeToken)return;app.innerHTML=hero('Macro workshop','Less friction.<br><em>More control.</em>','Create a basic targeting macro from a preserved ability. Copy it into the game’s macro editor and test it on your realm.')+'<div class="card"><div class="toolbar"><label>Class <select id="macro-class">'+classes.map(x=>'<option value="'+x.key+'" '+(c.key===x.key?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></label><label>Ability <select id="macro-spell">'+[...new Map(data.nodes.filter(n=>!n.isPassive).map(n=>[n.name.trim(),n])).values()].sort((a,b)=>a.name.localeCompare(b.name)).map(n=>'<option>'+esc(n.name.trim())+'</option>').join('')+'</select></label></div><label>Targeting <select id="macro-type"><option value="normal">Current target</option><option value="mouseover-help">Mouseover friendly / normal fallback</option><option value="mouseover-harm">Mouseover enemy / normal fallback</option><option value="focus">Focus enemy / current target</option><option value="self">Always cast on yourself</option></select></label><pre id="macro-output" class="macro-code"></pre><button id="copy-macro" class="button">Copy macro</button><p class="muted">Original macro templates. Whether a spell permits a target or action depends on its in-game behavior. Names use the preserved English spell labels.</p></div><h2>Useful basics</h2><div class="cards"><article class="card"><h3>Mouseover targeting</h3><p>Cast on the unit under your cursor without changing your selected target. Friendly and enemy conditions keep the targeting explicit.</p></article><article class="card"><h3>Focus targeting</h3><p>Keep a priority enemy as your focus while targeting something else. The generated macro falls back to your current target.</p></article><article class="card"><h3>One action at a time</h3><p>These templates target a single cast. They do not automate rotations or make combat decisions.</p></article></div>';const paint=()=>{const n=$('#macro-spell').value,type=$('#macro-type').value,cond={normal:'', 'mouseover-help':'[@mouseover,help,nodead][] ', 'mouseover-harm':'[@mouseover,harm,nodead][] ',focus:'[@focus,harm,nodead][] ',self:'[@player] '}[type];$('#macro-output').textContent='#showtooltip '+n+'\n/cast '+cond+n;};$('#macro-class').onchange=e=>go('macros',{class:e.target.value});$('#macro-spell').onchange=paint;$('#macro-type').onchange=paint;$('#copy-macro').onclick=()=>copy($('#macro-output').textContent,'Macro copied.');paint();}
