const addonPaint=()=>{const q=$('#addon-search').value.toLowerCase(),cat=$('#addon-filter').value,items=community.addons.filter(x=>(!cat||addonGroup(x)===cat)&&[x.name,x.category,x.compatibility,x.maturity,x.summary,...x.tags].join(' ').toLowerCase().includes(q)),groups=new Map();for(const x of items){const group=addonGroup(x);if(!groups.has(group))groups.set(group,[]);groups.get(group).push(x);}$('#addon-count').textContent=items.length+' community addon listings · '+groups.size+' categories';$('#addon-results').innerHTML=[...groups].sort((a,b)=>a[0].localeCompare(b[0])).map(([name,rows])=>'<details class="catalog-subsection" '+((cat||q)?'open':'')+'><summary>'+esc(name)+' <span>'+rows.length+' addons</span></summary><div class="addon-grid">'+rows.map(x=>'<article class="addon-card"><div class="addon-card-top"><span class="eyebrow">'+esc(x.category)+'</span><span class="tag">'+esc(x.compatibility)+'</span></div><h3>'+esc(x.name)+'</h3><p>'+esc(x.summary)+'</p><div class="addon-maturity">'+esc(x.maturity)+'</div><div class="addon-actions"><a class="button" href="'+esc(x.download)+'" target="_blank" rel="noopener">Download / project ↗</a><a class="button secondary" href="'+esc(x.source)+'" target="_blank" rel="noopener">Source & notes</a></div></article>').join('')+'</div></details>').join('')||empty('No addons match these filters.');};
$('#addon-search').oninput=addonPaint;$('#addon-filter').onchange=addonPaint;addonPaint();
const waPaint=()=>{const q=$('#aura-search').value.toLowerCase(),kind=$('#aura-kind').value,cl=$('#aura-class').value;let classRows=[],packRows=[];if(!kind||kind==='Class pack'||kind==='Specialization pack'){classRows=waEntries.filter(x=>(!cl||x.class===cl)&&(!kind||x.kind===kind)&&[x.class,x.spec,x.kind].join(' ').toLowerCase().includes(q)).map(x=>{const sourceUrl='https://github.com/'+catalog.source+'/tree/main/'+x.path.split('/').slice(0,-1).join('/');return {class:x.class,html:'<article class="aura-pack"><div class="aura-pack-top"><span class="eyebrow">'+esc(x.class)+'</span><span class="tag">'+esc(x.kind)+'</span></div><h3>'+esc(x.spec)+'</h3><div class="aura-pack-actions"><button class="button" data-aura-copy="'+esc(x.url)+'">Copy import string</button><a class="button secondary" href="'+esc(x.url)+'" target="_blank" rel="noopener">Download / raw export ↗</a><a class="button secondary" href="'+esc(sourceUrl)+'" target="_blank" rel="noopener">Source files ↗</a></div></article>'};});classRows=classRows.concat(communityPacks.filter(x=>(!cl||x.class===cl)&&(!kind||x.kind===kind)&&[x.class,x.name,x.kind,x.summary,x.status].join(' ').toLowerCase().includes(q)).map(x=>({class:x.class,html:'<article class="aura-pack encounter-pack"><div class="aura-pack-top"><span class="eyebrow">'+esc(x.class)+' · '+esc(x.sourceName)+'</span><span class="tag">'+esc(x.kind)+'</span></div><h3>'+esc(x.name)+'</h3><p>'+esc(x.summary)+'</p><small class="pack-status">'+esc(x.status)+'</small><div class="aura-pack-actions"><a class="button" href="'+esc(x.url)+'" target="_blank" rel="noopener">Open pack / import ↗</a><a class="button secondary" href="'+esc(sourcePage(x))+'" target="_blank" rel="noopener">Source page ↗</a></div></article>'})));}if(!cl&&(!kind||kind==='Dungeon pack'||kind==='Raid pack'))packRows=encounters.filter(x=>['Dungeons','Raids'].includes(x.scope)&&(!kind||(kind==='Dungeon pack'?x.scope==='Dungeons':x.scope==='Raids'))&&[x.name,x.scope,x.game,x.sourceName,x.summary,x.status].join(' ').toLowerCase().includes(q));const classGroups=new Map();for(const x of classRows){if(!classGroups.has(x.class))classGroups.set(x.class,[]);classGroups.get(x.class).push(x.html);}const classHtml=classRows.length?'<details class="catalog-subsection wa-class-groups"><summary>Class & specialization packs <span>'+classRows.length+' packs · '+classGroups.size+' classes</span></summary><div class="catalog-class-list">'+[...classGroups].sort((a,b)=>a[0].localeCompare(b[0])).map(([name,cards])=>'<details class="catalog-subsection" '+((cl===name||q)?'open':'')+'><summary>'+esc(name)+' <span>'+cards.length+' packs</span></summary><div class="aura-grid">'+cards.join('')+'</div></details>').join('')+'</div></details>':'';const encounterHtml=['Dungeons','Raids'].map(scope=>{const rows=packRows.filter(x=>x.scope===scope);return rows.length?'<details class="catalog-subsection" '+(kind===(scope==='Dungeons'?'Dungeon pack':'Raid pack')?'open':'')+'><summary>'+scope+' encounter packs <span>'+rows.length+' packs</span></summary><div class="aura-grid">'+rows.map(x=>'<article class="aura-pack encounter-pack"><div class="aura-pack-top"><span class="eyebrow">'+esc(x.scope)+' · '+esc(x.game)+'</span><span class="tag">'+esc(x.sourceName)+'</span></div><h3>'+esc(x.name)+'</h3><p>'+esc(x.summary)+'</p><small class="pack-status">'+esc(x.status)+'</small><div class="aura-pack-actions"><a class="button" href="'+esc(x.url)+'" target="_blank" rel="noopener">Open pack / import ↗</a><a class="button secondary" href="'+esc(sourcePage(x))+'" target="_blank" rel="noopener">Source page ↗</a></div></article>').join('')+'</div></details>':'';}).join('');$('#aura-count').textContent=(classRows.length+packRows.length)+' packs · '+classRows.length+' class/spec · '+packRows.length+' encounter'+(cl?' · filtered to '+cl:'');$('#aura-results').innerHTML=classHtml+encounterHtml||empty('No packs match these filters. Clear the class filter to browse encounter packs.');for(const b of $$('[data-aura-copy]'))b.onclick=async()=>{b.disabled=true;b.textContent='Loading export…';try{const r=await fetch(b.dataset.auraCopy);if(!r.ok)throw Error('Export unavailable');await copy(await r.text(),'WeakAura import string copied.');}catch{toast('Could not copy the export here. Open the raw export and copy it from the source.');}finally{b.disabled=false;b.textContent='Copy import string';}};};
