function mdInline(text){return esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(text){const lines=text.split('\n');let out='',inCode=false,table=[];function flush(){if(!table.length)return;const rows=table.filter(l=>!/^\s*\|?[\s:|-]+\|\s*$/.test(l));out+='<div class="doc-table"><table>'+rows.map((r,i)=>'<tr>'+r.trim().replace(/^\||\|$/g,'').split('|').map(v=>'<'+(!i?'th':'td')+'>'+mdInline(v.trim())+'</'+(!i?'th':'td')+'>').join('')+'</tr>').join('')+'</table></div>';table=[];}
for(const line of lines){if(/^```/.test(line)){flush();out+=inCode?'</code></pre>':'<pre><code>';inCode=!inCode;continue;}if(inCode){out+=esc(line)+'\n';continue;}if(/^\s*\|/.test(line)){table.push(line);continue;}flush();const h=line.match(/^(#{1,4})\s+(.*)/);if(h){out+='<h'+h[1].length+'>'+mdInline(h[2])+'</h'+h[1].length+'>';continue;}if(/^\s*[-*]\s+/.test(line)){out+='<p>• '+mdInline(line.replace(/^\s*[-*]\s+/,''))+'</p>';continue;}if(line.trim())out+='<p>'+mdInline(line)+'</p>';}flush();if(inCode)out+='</code></pre>';return out;}
async function libraryPage(params,token){const docs=await json('research.json');if(token!==routeToken)return;app.innerHTML=hero('Sources & research · Provenance','The source room.<br><em>One place for the record.</em>','Browse BoneArchive’s source catalog, preserved captures, evidence notes, and data methods in one place. Original publishers and capture dates are recorded here.')+'<section class="feature-callout research-repo-callout"><div class="callout-mark" aria-hidden="true">⌕</div><div><span class="eyebrow">21 DOCUMENTED RESEARCH RECORDS</span><h2>CoA-Research keeps the evidence connected.</h2><p>Browse the full repository for source datasets, spell and class notes, recovered historical gear, combat and addon engineering, and each record’s limits. Use its provenance and confidence labels to expand BoneArchive’s ability search, talent guides, gear comparisons, and addon notes without treating unverified references as live-client facts.</p><a href="https://github.com/downingwow/CoA-Research" target="_blank" rel="noopener">Open CoA-Research on GitHub ↗</a></div></section>'+'<input id="library-filter" class="library-search" type="search" aria-label="Search research documents" placeholder="Search sources, bosses, items, balance…"><div class="research-layout"><nav class="research-list" aria-label="Research documents" id="research-list"></nav><article id="research-doc" class="research-doc"></article></div>';function open(doc){$('#research-doc').innerHTML=markdown(doc.content)+'<p><a href="https://github.com/downingwow/CoA-Research/blob/main/'+esc(doc.path)+'" target="_blank" rel="noopener">Original document ↗</a></p>';$$('[data-doc]').forEach(b=>b.classList.toggle('active',b.dataset.doc===doc.path));}function paint(){const q=$('#library-filter').value.toLowerCase();const shown=docs.filter(d=>[d.path,d.content].join(' ').toLowerCase().includes(q));$('#research-list').innerHTML=shown.map(d=>'<button data-doc="'+esc(d.path)+'">'+esc(d.content.match(/^#\s+(.+)/)?.[1]||d.path.split('/').pop())+'</button>').join('');$$('[data-doc]').forEach(b=>b.onclick=()=>open(docs.find(d=>d.path===b.dataset.doc)));if(shown.length)open(shown.find(d=>d.path===params.get('doc'))||shown.find(d=>d.path==='sources/INDEX.md')||shown[0]);else $('#research-doc').innerHTML=empty('No matching research documents.');}$('#library-filter').oninput=paint;paint();}
function wireImages(){for(const img of $$('img',app)){if(img.dataset.fallback)continue;img.dataset.fallback='1';img.addEventListener('error',()=>{if(img.dataset.iconKey&&!img.dataset.wowheadRetry){img.dataset.wowheadRetry='1';img.src='https://wow.zamimg.com/images/wow/icons/large/'+encodeURIComponent(img.dataset.iconKey)+'.jpg';return;}if(img.dataset.iconKey){img.remove();img.parentElement?.classList.add('icon-missing');}else img.remove();});}}
async function copy(text,message){try{await navigator.clipboard.writeText(text);toast(message);}catch{toast('Clipboard access is unavailable. Select and copy the displayed text.');}}
function download(name,text,type){const a=document.createElement('a'),href=URL.createObjectURL(new Blob([text],{type}));a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),2000);}
function go(view,params={}){navigate(new URL(url(view,params),location.href));}
function closeNavigationMenus(){document.querySelectorAll('.nav-dropdown[open]').forEach(x=>x.open=false);const directory=document.querySelector('.classnav');if(directory)directory.classList.remove('open');const toggle=$('.menu-toggle');if(toggle)toggle.setAttribute('aria-expanded','false');}
function navigate(target){const u=target instanceof URL?target:new URL(target,location.href);if(u.origin!==location.origin){location.href=u.href;return;}closeNavigationMenus();history.pushState({},'',u);render();window.scrollTo({top:0,behavior:'instant'});}
function addPageContents(view){if(view==='home'||view==='addons'||view==='gear')return;const headings=$$('h2',app).filter(h=>h.textContent.trim());if(headings.length<2)return;const links=[],used=new Map();for(const h of headings){let id=h.id||slug(h.textContent)||'section',n=used.get(id)||0;used.set(id,n+1);if(n)id+='-'+(n+1);h.id=id;links.push('<a href="#'+esc(id)+'">'+esc(h.textContent.trim())+'</a>');}if(!links.length)return;const heroNode=$('.hero',app);if(!heroNode)return;const shell=document.createElement('div'),main=document.createElement('main'),nav=document.createElement('details');shell.className='content-with-index';main.className='indexed-content';nav.className='onpage-nav';nav.open=true;nav.innerHTML='<summary><span class="index-kicker">GUIDE INDEX</span><strong>On this page</strong><small>'+links.length+' sections</small></summary><nav class="onpage-panel" aria-label="On this page">'+links.join('')+'</nav>';let node=heroNode.nextSibling;while(node){const next=node.nextSibling;main.appendChild(node);node=next;}shell.append(nav,main);heroNode.after(shell);app.classList.add('has-section-index');nav.querySelectorAll('.onpage-panel a').forEach(a=>a.onclick=e=>{e.preventDefault();const target=$('#'+CSS.escape(decodeURIComponent(a.hash.slice(1))));if(target){history.replaceState({},'',a.hash);target.scrollIntoView({behavior:'smooth',block:'start'});if(window.matchMedia('(max-width: 900px)').matches)nav.open=false;}});if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));}}, {rootMargin:'-18% 0px -70% 0px'});headings.forEach(h=>observer.observe(h));}}
async function render(){const token=++routeToken;builder=null;hideTip();closeNavigationMenus();const params=new URLSearchParams(location.search),view=params.get('view')||'home';document.title='BoneArchive · '+({home:'Conquest research archive',builder:'Talent builder',class:'Class guide',spells:'Ability index',search:'Archive search',picker:'Find my spec',library:'Sources & research',saved:'My builds',macros:'Macro workshop',gear:'Gear & BiS',addons:'Addons & WeakAuras',rankings:'Spec comparison'}[view]||'Conquest research archive');renderSidebar(params.get('class'));app.innerHTML='<div class="loading" role="status">Opening the archive…</div>';try{await ({home, rankings:rankingsPage, class:classPage,builder:builderPage,saved:savedPage,search:searchPage,spells:spellsPage,picker:pickerPage,macros:macrosPage,addons:addonsPage,gear:gearPage,library:libraryPage}[view]||home)(params,token);wireImages();addPageContents(view);}catch(e){if(token!==routeToken)return;app.innerHTML='<div class="empty error"><h2>Could not open this part of the archive</h2><p>'+esc(e.message)+'</p><button class="button" id="retry-page">Try again</button></div>';$('#retry-page').onclick=render;}}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&['/','/index.html',location.pathname.endsWith('/index.html')?location.pathname:'__none__'].includes(u.pathname)){e.preventDefault();navigate(u);}});
window.addEventListener('popstate',()=>{render();window.scrollTo(0,0);});window.addEventListener('scroll',hideTip,{passive:true});window.addEventListener('resize',hideTip);document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip();});
$('.menu-toggle').onclick=e=>{const directory=document.querySelector('.classnav'),open=directory.classList.contains('open');document.querySelectorAll('.nav-dropdown[open]').forEach(x=>x.open=false);directory.classList.toggle('open',!open);e.currentTarget.setAttribute('aria-expanded',String(!open));};document.querySelectorAll('.nav-dropdown').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){document.querySelectorAll('.nav-dropdown[open]').forEach(x=>{if(x!==d)x.open=false;});const directory=document.querySelector('.classnav');if(directory)directory.classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');}}));document.addEventListener('click',e=>{if(!e.target.closest('.nav-dropdown')&&!e.target.closest('.menu-toggle')&&!e.target.closest('.classnav'))closeNavigationMenus();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigationMenus();});$('.searchbox').onsubmit=e=>{e.preventDefault();go('search',{q:$('#global-search').value});};
Promise.all([json('classes.json'),json('essence.json')]).then(([c,e])=>{classes=c;curves=e;render();}).catch(e=>{app.innerHTML=empty('The archive could not load: '+e.message+'. Please refresh to retry.');});
